import inspect
import re
import sys
import time
from pathlib import Path

import pytest
import torch

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))
sys.path.insert(0, str(ROOT / "tools"))

PROBLEM = "muse_attention_decode"
MEAS = ROOT / "kernels" / PROBLEM / "measure_verify_v1.py"
V3 = ROOT / "kernels" / PROBLEM / "sonnet_v3.py"
needs_cuda = pytest.mark.skipif(not torch.cuda.is_available(), reason="needs a CUDA GPU")

SMALL_VERIFY = dict(batch=3, ctx=1800, dist="coherent", heads="tp8", layer="full", page=1, q_len=8, spread="agentic")
SMALL_DECODE = dict(batch=3, ctx=1800, dist="coherent", heads="tp8", layer="full", page=1, spread="agentic")


def _load(name="_measure_verify_v1", path=MEAS):
    spec = importlib.util.spec_from_file_location(name, path)
    m = importlib.util.module_from_spec(spec)
    m._MV_NO_AUTORUN = True              # attention has no prepare(): the study would otherwise run at import
    spec.loader.exec_module(m)
    return m


@pytest.fixture()
def mod():
    return _load()


# ------------------------------------------------------------------------------------------------------------ no GPU
def test_source_rules_and_in_sync_with_generator():
    src = MEAS.read_text()
    compile(src, "measure_verify_v1.py", "exec")
    lines = src.splitlines()
    assert lines[0] == "# okc: problem=muse_attention_decode" and "MEASUREMENT-ONLY" in lines[1] and "NEVER submit" in lines[1]
    for banned in ("subprocess", "urllib", "requests", "socket", "os.system", "import os", "environ", ".tolist(", "from reference", "import reference", "__import__", "_getframe"):
        assert banned not in src, banned
    import gen_measure_verify_v1 as gen
    assert gen.build() == src, "regenerate: .venv/bin/python tools/gen_measure_verify_v1.py"
    assert "MEASUREMENT-ONLY" not in V3.read_text() and "_mv_" not in V3.read_text()


def test_kernel_fn_is_sonnet_v3_verbatim():
    v = V3.read_text().splitlines()
    m = MEAS.read_text().splitlines()
    start = next(i for i, line in enumerate(m) if line.startswith("# sonnet_v3 -- v2 with new kernels"))
    assert m[start:start + len(v) - 1] == v[1:], "sonnet_v3 is not embedded verbatim"


def test_budget_and_cases(mod):
    assert mod._MV_BUDGET_S <= 240 and mod._MV_REPS == 5 and len(mod._MV_SEEDS) == 3 and mod._MV_MAX_BYTES <= 14000
    idx = [i for i, _, _ in mod._MV_CASES]
    assert idx == [9, 11, 7, 3, 5]
    for i, label, c in mod._MV_CASES:
        assert c["layer"] == "full" and c["ctx"] == 80000 and c["page"] == 1 and c["dist"] == "coherent"
        assert (c.get("q_len", 1) == 8) == label.startswith("verify")
    assert {c["batch"] for _, _, c in mod._MV_CASES} == {1, 16, 32}
    names = [n for n, _ in mod._MV_VARIANTS]
    for want in ("base", "GATHER", "NOEXP", "NOCVT", "EXPSPLIT25", "EXPSPLIT50", "MMAONLY", "RED", "PROGx2", "BN128", "ST2", "ST3"):
        assert want in names


def _poly_torch(x, coefs):
    """The kernel's _mv_exp2_poly operation by operation, in FP32 on the CPU."""
    x = torch.clamp(x, min=-126.0)
    t = x + 12582912.0
    f = x - (t - 12582912.0)
    p = f * coefs[0] + coefs[1]
    for c in coefs[2:]:
        p = p * f + c
    bits = p.view(torch.int32) + (t.view(torch.int32) << 23)
    return bits.view(torch.float32)


def test_exp2_polynomial_error_below_2e7_in_fp32(mod):
    src = inspect.getsource(mod._mv_exp2_poly.fn)
    lits = [float(v) for line in src.splitlines() if line.startswith("    p = ") for v in re.findall(r"\d+\.\d+(?:e-?\d+)?", line)]
    assert tuple(lits) == mod._MV_EXP2_C, (lits, mod._MV_EXP2_C)    # kernel text == the table
    g = torch.Generator().manual_seed(0)
    x = torch.cat([-100 * torch.rand(4_000_000, generator=g), -20 * torch.rand(4_000_000, generator=g), torch.linspace(-30, 0, 2_000_000),
                   torch.tensor([0.0, -0.5, -1.0, -0.25, -63.5, -125.9])])
    ref = torch.exp2(x.double())
    got = _poly_torch(x, mod._MV_EXP2_C).double()
    rel = float(((got - ref).abs() / ref).max())
    assert rel < 2e-7, rel
    # masked logits (-inf) and anything below -126 give ~1e-38, i.e. 0 once P is rounded to FP16; the row maximum gives exactly 1
    tiny = _poly_torch(torch.tensor([float("-inf"), -500.0, -126.0]), mod._MV_EXP2_C)
    assert float(tiny.max()) < 2e-38 and float(_poly_torch(torch.tensor([0.0]), mod._MV_EXP2_C)) == pytest.approx(1.0, abs=2e-7)


def _fake_results(mod, with_bad=False):
    names = [n for n, _ in mod._MV_VARIANTS]
    results = {}
    for idx, label, case in mod._MV_CASES:
        v = {"board": dict(us=[100.0, 101.0, 99.0], err=[], row=[], perr=[], ok=[], counts=None, status="ok")}
        for i, n in enumerate(names):
            base = n in mod._MV_CHECKED
            v[n] = dict(us=[100.0 - 3 * i, 101.0 - 3 * i, 99.0 - 3 * i], err=[1e-6] * 3 if base else [], row=[0.01] * 3 if base else [],
                        perr=[1e-7, None, 2e-7] if base else [], ok=[True, True, not with_bad] if base else [],
                        counts=dict(regs=185, spills=0, smem=69632, ex2=84, cpasync=32, wgmma=18, mma=0, cvt=236, ldg=28, bar=25) if idx == 9 else None, status="ok")
        v["BN128"] = dict(us=[], err=[], row=[], perr=[], ok=[], counts=None, status="fail OutOfResources: " + "x" * 200)
        results[idx] = dict(label=label, case=case, seeds=list(mod._MV_SEEDS), v=v if label.startswith("verify") else {"board": v["board"]})
    return results


def test_render_size_summary_first_and_format(mod):
    text = mod._mv_render(_fake_results(mod), dict(gpu="NVIDIA_H200", ovh=3.9, secs=120.0))
    assert len(text.encode()) <= 14000
    lines = text.splitlines()
    first_b = next(i for i, line in enumerate(lines) if line.startswith("B "))
    assert lines[0].startswith("S attn verify v1:") and all(line[:2] in ("S ", "C ") for line in lines[:first_b])
    assert any(line.startswith("S #9 shares of base") for line in lines[:first_b]) and any(line.startswith("C base regs=185") for line in lines[:first_b])
    assert any(line.startswith("S EXPSPLIT vs base") for line in lines[:first_b])
    for line in lines[first_b:]:
        assert re.fullmatch(r"B attn #\d+ seed=\d+ \| \w+ (us=\d+\.\d\d( x=\d+\.\d\d)?( err=\S+( BAD)?)?|fail .*)", line), line
    assert any(" | EXPSPLIT50 us=" in line and "err=1.0e-06/1.0e-07" in line for line in lines)
    bad = mod._mv_render(_fake_results(mod, with_bad=True), dict(gpu="x", ovh=0.0, secs=1.0))
    assert " BAD" in bad
    # a twin faster than the GATHER / MMAONLY floor is called out
    res = _fake_results(mod)
    res[9]["v"]["NOEXP"]["us"] = [1.0, 1.0, 1.0]
    assert "INVALID twins" in mod._mv_render(res, dict(gpu="x", ovh=0.0, secs=1.0))
    # worst case: many seeds / variants still fit
    mod._MV_SEEDS = tuple(range(40))
    big = _fake_results(mod)
    for r in big.values():
        r["seeds"] = list(range(40))
        for x in r["v"].values():
            for k in ("us", "err", "row", "perr", "ok"):
                x[k] = x[k] * 14
    text = mod._mv_render(big, dict(gpu="x", ovh=0.0, secs=1.0))
    assert len(text.encode()) <= 14000 and "dropped for the 14 KB cap" in text


def test_cmp_matches_the_organisers_compare(mod):
    sys.path.insert(0, str(ROOT / "problems" / PROBLEM))
    try:
        import checks
    finally:
        sys.path.pop(0)
    g = torch.Generator().manual_seed(1)
    ref = torch.randn(4, 8, 1024, generator=g).to(torch.bfloat16)
    for scale in (0.0, 0.5, 2.0, 40.0):
        out = (ref.float() * (1 + 1e-3 * scale * torch.randn(ref.shape, generator=g))).to(torch.bfloat16)
        assert mod._mv_cmp(out, ref)[0] == checks.compare(out, ref, mod._MV_TOL)[0], scale
    bad = ref.clone()
    bad[1, 2] *= 1.9
    assert mod._mv_cmp(bad, ref)[0] == checks.compare(bad, ref, mod._MV_TOL)[0]
    nan = ref.clone()
    nan[0, 0, 0] = float("nan")
    assert not mod._mv_cmp(nan, ref)[0]


# ------------------------------------------------------------------------------------------------------------ dev GPU
@needs_cuda
def test_base_is_bitwise_the_board_kernel_and_expsplit_in_bound(mod):
    data = mod._tr_generate_input(**SMALL_VERIFY, seed=5)
    board = mod.kernel_fn(data).clone()
    outs = {}
    for name, v in mod._MV_VARIANTS:
        if v.get("red") or v.get("var") in (1, 2, 3, 4):
            continue
        cfg = mod._mv_cfg(v)
        pl = mod._mv_plan(data, cfg)
        bufs = mod._mv_bufs(data, pl)
        mod._mv_launch(data, cfg, v.get("var", 0), pl, bufs)
        torch.cuda.synchronize()
        outs[name] = bufs
    assert torch.equal(outs["base"]["out"], board)
    for n in ("EXPSPLIT25", "EXPSPLIT50", "PROGx2", "PROGd2", "ST3", "ST2", "W8"):
        ok, err, row = mod._mv_cmp(outs[n]["out"], board)
        assert ok and err < 1e-3 and row < 0.5, (n, err, row)
    for n in ("EXPSPLIT25", "EXPSPLIT50"):
        assert float((outs[n]["part_l"] - outs["base"]["part_l"]).norm() / outs["base"]["part_l"].norm()) < 1e-4      # p is rounded to FP16 before P.V: 1e-7 in p is far below it
        assert not torch.equal(outs[n]["part_l"], outs["base"]["part_l"])                                      # ... but the polynomial really ran (l sums FP32 p)


@needs_cuda
def test_twins_are_not_deletable(mod):
    data = mod._tr_generate_input(**SMALL_VERIFY, seed=6)
    cfg = mod._mv_cfg({})
    pl = mod._mv_plan(data, cfg)
    bufs = mod._mv_bufs(data, pl)
    mod._mv_launch(data, cfg, 1, pl, bufs)                       # GATHER: the sink holds the XOR fold of every loaded word
    torch.cuda.synchronize()
    sink = bufs["sink"][: pl["batch"] * pl["hkv"] * (pl["nsplit"] + 1)].view(pl["batch"], pl["hkv"], pl["nsplit"] + 1)[:, 0::2]
    seq = data["seq_lens"].tolist()
    used = [(s * pl["split_len"] < seq[b]) for b in range(pl["batch"]) for s in range(pl["nsplit"])]
    assert any(used) and int((sink[:, :, : pl["nsplit"]] != 0).sum()) >= 0.9 * sum(used)
    for var in (2, 3, 4):                                          # MMAONLY / NOEXP / NOCVT feed their results into the partials
        b2 = mod._mv_bufs(data, pl)
        mod._mv_launch(data, cfg, var, pl, b2)
        torch.cuda.synchronize()
        fin = b2["part_o"][torch.isfinite(b2["part_o"])]
        assert fin.numel() > 0 and float(fin.abs().sum()) > 0.0, var


@needs_cuda
def test_study_end_to_end_small_and_budget_guard(mod, capsys, monkeypatch):
    monkeypatch.setattr(mod, "_MV_CASES", [(9, "verify16", SMALL_VERIFY), (3, "decode16", SMALL_DECODE)])
    monkeypatch.setattr(mod, "_MV_SEEDS", (11, 12))
    mod._MV_T0 = time.perf_counter()
    mod._mv_study()
    out = capsys.readouterr().out
    lines = out.splitlines()
    assert lines[0].startswith("S attn verify v1:") and len(out.encode()) <= 14000
    for n, _ in mod._MV_VARIANTS:
        assert any(re.match(rf"B attn #9 seed=11 \| {n} us=", line) for line in lines), n
    assert any(re.match(r"B attn #3 seed=12 \| board us=", line) for line in lines)
    assert any(line.startswith("S EXPSPLIT vs base") and "no error" not in line for line in lines)
    assert not any(" BAD" in line for line in lines), out
    # nothing starts after the budget: a study that has used its 240 s skips the lot and still prints
    mod._MV_T0 = time.perf_counter() - mod._MV_BUDGET_S
    t = time.perf_counter()
    mod._mv_study()
    assert time.perf_counter() - t < 30
    out2 = capsys.readouterr().out
    assert out2.startswith("S attn verify v1:") and "skipped (budget)" in out2 and "B attn #9" not in out2


# ------------------------------------------------------------------------------------------------------------ sm_90 compile
# LAST in the file on purpose: ptx_audit.Capture patches get_device_capability, which Triton's driver caches for the process; real launches must come before it.
@needs_cuda
def test_variants_compile_for_sm90_and_counts_relate(mod):
    from tools import ptx_audit as pa
    data = mod._tr_generate_input(**SMALL_VERIFY, seed=3)
    with pa.Capture() as cap:                       # torch.cuda.get_device_capability -> (9, 0): the file takes its Hopper branches; nothing runs
        mod.kernel_fn(data)
        for name, v in mod._MV_VARIANTS:
            if v.get("red"):
                continue
            cfg = mod._mv_cfg(v)
            pl = mod._mv_plan(data, cfg)
            cap.case = name
            mod._mv_launch(data, cfg, v.get("var", 0), pl, mod._mv_bufs(data, pl))
    counts = {}
    for r in cap.records:
        if r["name"] == "_full_kernel":
            counts["board"] = pa.compile_record(r)
        elif r["name"] == "_mv_full_kernel":
            counts[r["case"]] = pa.compile_record(r)
    assert set(counts) == {"board"} | {n for n, v in mod._MV_VARIANTS if not v.get("red")}
    for n, c in counts.items():
        print(f"AUDIT {n}: regs={c['regs']} spills={c['spills']} smem={c['smem']} ex2={c['ex2']} cp.async={c['cp.async']} wgmma={c['wgmma']}")
        assert c["spills"] == 0 or n in ("GATHER",), (n, c["spills"])
    b, base = counts["board"], counts["base"]
    for k in ("regs", "spills", "smem", "ex2", "cp.async", "wgmma", "cvt", "ld.global", "bar.sync", "st.global"):
        assert b[k] == base[k], (k, b[k], base[k])                 # the switch-off copy IS the board kernel
    assert (b["cp.async"], b["wgmma"], b["ex2"], b["regs"]) == (32, 18, 84, 185)   # design/breakdown/ptx-audit.md
    assert counts["EXPSPLIT50"]["ex2"] == base["ex2"] - 32 and counts["EXPSPLIT25"]["ex2"] == base["ex2"] - 16
    assert counts["EXPSPLIT25"]["smem"] == base["smem"] and counts["EXPSPLIT50"]["smem"] == base["smem"]    # the splits stay in registers
    assert counts["EXPSPLIT50"]["bar.sync"] == base["bar.sync"] and counts["EXPSPLIT25"]["bar.sync"] == base["bar.sync"]
    assert counts["NOEXP"]["ex2"] < counts["EXPSPLIT50"]["ex2"] and counts["MMAONLY"]["ex2"] == 0
    assert counts["NOCVT"]["cvt"] < base["cvt"] and counts["NOCVT"]["cp.async"] == base["cp.async"]
    assert counts["MMAONLY"]["cp.async"] == base["cp.async"] and counts["MMAONLY"]["wgmma"] < base["wgmma"]
    assert counts["GATHER"]["wgmma"] < base["wgmma"] and counts["GATHER"]["ld.global"] >= base["ld.global"]    # loads kept (global loads, no pipeline)
    assert counts["ST3"]["cp.async"] < base["cp.async"] and counts["ST2"]["cp.async"] < counts["ST3"]["cp.async"]
    assert counts["PROGx2"] == counts["base"] == counts["PROGd2"]                                          # launch-config only: same code
